fn find_max_in_prefix(v: &[i32], end: usize) -> (i32, usize) {
    // We assume end < v.len()
    // Initialize max to the first element in the prefix
    let mut max_val = v[0];
    let mut max_idx = 0;

    // Iterate over the prefix [0..=end]
    for i in 1..=end {
        if v[i] > max_val {
            max_val = v[i];
            max_idx = i;
        }
    }
    (max_val, max_idx)
}

fn find_min_in_suffix(v: &[i32], start: usize) -> (i32, usize) {
    // Assume start < v.len()
    let mut min_val = v[start];
    let mut min_idx = start;

    // Iterate over suffix [start..v.len())
    for i in (start + 1)..v.len() {
        if v[i] < min_val {
            min_val = v[i];
            min_idx = i;
        }
    }
    (min_val, min_idx)
}

fn barrier(v: &[i32], p: usize) -> bool {
    // If p is the last index, vacuously true by problem statement
    if p + 1 >= v.len() {
        return true;
    }

    let (max_prefix_val, _) = find_max_in_prefix(v, p);
    let (min_suffix_val, _) = find_min_in_suffix(v, p + 1);

    max_prefix_val < min_suffix_val
}